class Song {
  constructor(title) {
    this.title = title;
  }

  play() {
    return `Playing ${this.title}`;
  }
}

Song.prototype.stop = () => "Stopped";

const seen = [];
for (const key in new Song("Intro")) seen.push(key);

console.log(seen.join(","));
console.log(Object.keys(new Song("Intro")).join(","));
console.log("play" in new Song("Intro"));
